<?php
require_once __DIR__ . '/../includes/auth-check.php';
require_once __DIR__ . '/../includes/admin-ui.php';
admin_require_permission($pdo,$admin,'manage_analytics');
$enabled=(bool)setting($pdo,'site_analytics_enabled',false);
$daily=$pdo->query("SELECT DATE(created_at) AS event_day,COUNT(CASE WHEN event_type='page_view' THEN 1 END) AS views,COUNT(CASE WHEN event_type='generator_run' THEN 1 END) AS generator_runs,COUNT(DISTINCT visitor_hash) AS approximate_visitors FROM site_events WHERE created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) GROUP BY DATE(created_at) ORDER BY event_day DESC")->fetchAll();
$topPages=$pdo->query("SELECT page_path,COUNT(*) AS views,COUNT(DISTINCT visitor_hash) AS visitors FROM site_events WHERE event_type='page_view' AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) GROUP BY page_path ORDER BY views DESC LIMIT 20")->fetchAll();
$affiliates=$pdo->query('SELECT a.label,a.slug,a.is_active,COUNT(c.id) AS clicks,COUNT(DISTINCT c.visitor_hash) AS visitors FROM affiliate_links a LEFT JOIN affiliate_clicks c ON c.affiliate_link_id=a.id AND c.clicked_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) GROUP BY a.id ORDER BY clicks DESC')->fetchAll();
$totalViews=(int)$pdo->query("SELECT COUNT(*) FROM site_events WHERE event_type='page_view' AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)")->fetchColumn();
$totalRuns=(int)$pdo->query("SELECT COUNT(*) FROM site_events WHERE event_type='generator_run' AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)")->fetchColumn();
$totalAffiliate=(int)$pdo->query("SELECT COUNT(*) FROM affiliate_clicks WHERE clicked_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY)")->fetchColumn();
admin_header($pdo,$admin,'Traffic report');
?>
<?php if(!$enabled):?><div class="notice notice-warning">First-party event collection is off. Enable it in <a href="<?=e(app_url('admin/settings.php'))?>">Site settings</a> only after reviewing your public privacy information.</div><?php endif;?>
<div class="admin-stats"><article class="admin-stat"><span>Page views · 30 days</span><strong><?=number_format($totalViews)?></strong><small>Aggregate first-party requests</small></article><article class="admin-stat"><span>Generator runs · 30 days</span><strong><?=number_format($totalRuns)?></strong><small>Root keywords are not stored</small></article><article class="admin-stat"><span>Affiliate redirects · 30 days</span><strong><?=number_format($totalAffiliate)?></strong><small>Ad clicks are not included</small></article><article class="admin-stat"><span>Event tracking</span><strong><?=$enabled?'On':'Off'?></strong><small>No raw IP stored by these event tables</small></article></div>
<div class="admin-columns"><section class="admin-card"><h2>Daily totals (UTC)</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Date</th><th>Page views</th><th>Generator runs</th><th>Approx. visitors*</th></tr></thead><tbody><?php foreach($daily as $row):?><tr><td><?=e($row['event_day'])?></td><td><?=number_format((int)$row['views'])?></td><td><?=number_format((int)$row['generator_runs'])?></td><td><?=number_format((int)$row['approximate_visitors'])?></td></tr><?php endforeach;?><?php if(!$daily):?><tr><td colspan="4">No daily events recorded.</td></tr><?php endif;?></tbody></table></div><p><small>*Daily unique counts are available only when ANALYTICS_SALT is configured and are approximate.</small></p></section>
<section class="admin-card"><h2>Top pages · 30 days</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Path</th><th>Views</th><th>Approx. visitors</th></tr></thead><tbody><?php foreach($topPages as $row):?><tr><td><code><?=e($row['page_path'])?></code></td><td><?=number_format((int)$row['views'])?></td><td><?=number_format((int)$row['visitors'])?></td></tr><?php endforeach;?><?php if(!$topPages):?><tr><td colspan="3">No page-view events recorded.</td></tr><?php endif;?></tbody></table></div></section></div>
<section class="admin-card"><h2>Affiliate link clicks · 30 days</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Link</th><th>Route</th><th>Clicks</th><th>Approx. visitors</th><th>Status</th></tr></thead><tbody><?php foreach($affiliates as $row):?><tr><td><?=e($row['label'])?></td><td><code>/go/<?=e($row['slug'])?></code></td><td><?=number_format((int)$row['clicks'])?></td><td><?=number_format((int)$row['visitors'])?></td><td><?= $row['is_active']?'Active':'Disabled' ?></td></tr><?php endforeach;?><?php if(!$affiliates):?><tr><td colspan="5">No affiliate redirects configured.</td></tr><?php endif;?></tbody></table></div><p>Affiliate redirects are separately measured. AdSense ad-click activity is not collected by the CMS.</p></section>
<?php admin_footer(); ?>
